let SAMP={};const SEL={};//
function loadSamples(){for(const k in SAMP){if(SEL[k])continue;const a=new Audio(SAMP[k]);a.preload='auto';try{a.load()}catch(e){}SEL[k]=a}}

function playS(k){if(!AU.on||!ROOT.isConnected||document.hidden)return;loadSamples();const base=SEL[k];if(!base)return;
  const a=base.paused||base.ended?base:base.cloneNode(true);try{a.currentTime=0}catch(e){}a.volume=.9;const p=a.play();if(p&&p.catch)p.catch(()=>{})}
for(const k of SNDKEYS)SND[k]=()=>playS(k);
