async function hop(h=7,q){setPose({by:1.6,sx:1.1,sy:.86});await sleep(150);   // anticipation: crouch
  if(!q)SND.hopUp();setPose({by:-h,sx:.94,sy:1.08});kick('earL',-120);kick('earR',120);await sleep(230);
  if(!q)SND.land();setPose({by:0,sx:1.08,sy:.9});await sleep(120);setPose({sx:1,sy:1});await sleep(160)}
async function flap(n=4,amp=10){setPose({earL:amp*.35,earR:-amp*.35});await sleep(110);   // opposite first
  for(let i=0;i<n;i++){const d=1-i/n;if(i===0&&!flap.q)SND.swish();setPose({earL:-amp*d,earR:amp*d});await sleep(150);setPose({earL:amp*d*.3,earR:-amp*d*.3});await sleep(130)}
  setPose({earL:0,earR:0});await sleep(350)}
let bubA=null,zzzA=[],popId=0;
function bubbleLoop(){popId++;$('bubblePop').getAnimations().forEach(a=>a.cancel());if(RM)return;bubA&&bubA.cancel();const b=$('bubbleIn');b.getAnimations().forEach(a=>a.cancel());
  bubA=b.animate([{transform:'scale(.2)'},{transform:'scale(1.2)',offset:.45},{transform:'scale(1.27)',offset:.55},{transform:'scale(.2)'}],{duration:3200,iterations:Infinity,easing:EIO});bubA.playbackRate=RATE}
function popBubble(){const b=$('bubbleIn');if($('bubble').classList.contains('hide'))return;SND.pop();if(RM){show('bubble',false);return}
  let sc=1;try{const m=new DOMMatrix(getComputedStyle(b).transform);sc=Math.max(.65,m.a)}catch(e){}
  bubA&&bubA.cancel();bubA=null;b.getAnimations().forEach(a=>a.cancel());
  b.animate([{transform:`scale(${sc})`,opacity:1},{transform:`scale(${sc*1.3})`,opacity:.9,offset:.5},{transform:`scale(${sc*1.4})`,opacity:0}],{duration:220,easing:EO,fill:'forwards'});
  const p=$('bubblePop');p.animate([{transform:`scale(${sc*.7})`,opacity:0},{transform:`scale(${sc*1.1})`,opacity:1,offset:.3},{transform:`scale(${sc*1.45})`,opacity:0}],{duration:380,delay:60,easing:EO});
  const id=++popId;setTimeout(()=>{if(id!==popId)return;show('bubble',false);b.getAnimations().forEach(a=>a.cancel())},460/RATE)}
function zzzLoop(){if(RM)return;zzzA.forEach(a=>a.cancel());zzzA=['z1','z2','z3'].map((c,i)=>{const a=ROOT.querySelector('#zzz .'+c).animate([{transform:'translate(0,10px)',opacity:0},{opacity:1,offset:.3},{transform:'translate(14px,-22px)',opacity:0}],{duration:2400,delay:i*500,iterations:Infinity,easing:EO});a.playbackRate=RATE;return a})}
function stopLoops(keepBubble){if(!keepBubble){bubA&&bubA.cancel();bubA=null;$('bubbleIn').getAnimations().forEach(a=>a.cancel())}zzzA.forEach(a=>a.cancel());zzzA=[]}



// magic release
function magicPart(part){if(!AU.on)return;const c=au();if(!c)return;const t=c.currentTime+.01;
  const bell=(f,at,dec,vol,partials=[[1,1],[2,.35],[3,.12]])=>partials.forEach(([m,v])=>{const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=f*m;
    g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(vol*v,at+.006);g.gain.exponentialRampToValueAtTime(.0005,at+dec/RATE);o.connect(g);g.connect(AU.master);const e=echo();if(e)g.connect(e);o.start(at);o.stop(at+dec/RATE+.05)});
  if(part==='inhale'){const d=.4/RATE,o=c.createOscillator(),g=c.createGain(),lp=c.createBiquadFilter();o.type='triangle';lp.type='lowpass';
    o.frequency.setValueAtTime(200,t);o.frequency.exponentialRampToValueAtTime(700,t+d);lp.frequency.setValueAtTime(500,t);lp.frequency.exponentialRampToValueAtTime(2600,t+d);
    g.gain.setValueAtTime(.0008,t);g.gain.exponentialRampToValueAtTime(.12,t+d*.95);g.gain.exponentialRampToValueAtTime(.0008,t+d+.05);o.connect(lp);lp.connect(g);g.connect(AU.master);o.start(t);o.stop(t+d+.08);
    noiz(.4,{ft:'lowpass',f0:300,f1:1300,q:.6,vol:.05,at:.36})}
  else if(part==='pop'){const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(240,t);o.frequency.exponentialRampToValueAtTime(560,t+.09);
    g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.34,t+.006);g.gain.exponentialRampToValueAtTime(.0008,t+.16);o.connect(g);g.connect(AU.master);o.start(t);o.stop(t+.2);
    tone(110,70,.18,{type:'sine',vol:.18,at:.004})}
  else if(part==='bell'){[523,659,784,1047].forEach((f,i)=>bell(f,t+i*.012,1.3,.09));[2093,2637,3136].forEach((f,i)=>bell(f,t+.08+i*.07,.5,.035,[[1,1]]))}}

